export function formatChatDayKey(value){
 const timezone='Asia/Shanghai';
 let date=null;
 if(typeof value==='number'||(typeof value==='string'&&/^\d{10,13}$/.test(value))){const n=Number(value);date=new Date(n<1e12?n*1000:n);}
 else if(typeof value==='string'&&value.trim()){
  const raw=value.trim(),local=/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?)?$/.exec(raw);
  if(local)return `${local[1]}-${local[2].padStart(2,'0')}-${local[3].padStart(2,'0')}`;
  date=new Date(raw);
 }else if(value instanceof Date)date=value;
 if(date&&Number.isFinite(date.getTime()))return new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
 return '日期未知';
}
export function formatChatTimestamp(value){
 const timezone='Asia/Shanghai';
 let date=null;
 if(typeof value==='number'||(typeof value==='string'&&/^\d{10,13}$/.test(value))){const n=Number(value);date=new Date(n<1e12?n*1000:n);}
 else if(typeof value==='string'&&value.trim()){
  const raw=value.trim(),local=/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::\d{2})?)?$/.exec(raw);
  if(local)return `${Number(local[2])}/${Number(local[3])}${local[4]!==undefined?` ${local[4].padStart(2,'0')}:${local[5]}`:''}`;
  date=new Date(raw);
 }
 if(date&&Number.isFinite(date.getTime()))return new Intl.DateTimeFormat('zh-CN',{timeZone:timezone,month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,hourCycle:'h23'}).format(date);
 return value?String(value).replace('T',' ').replace(/\.\d+Z?$/,'').slice(0,19):'';
}
function cleanTimelineDisplayText(value){
 const rejected=/(?:本地规则识别到|形成好感线索分|原文不足以判断|证据不足|无法(?:从聊天记录|由聊天记录|据此)?(?:判断|证明|推断)|不能(?:从聊天记录|据此)?(?:判断|证明|推断)|不等于真实好感|不代表真实好感|真实好感|心理动机|真实原因|其他原因)/u;
 return String(value||'').replace(/\s+/g,' ').split(/(?<=[，,；;。！？!?])/u).filter(part=>!rejected.test(part)).join('').replace(/[，,；;]+([。！？!?])/g,'$1').replace(/^[，,；;]+|[，,；;]+$/g,'').trim();
}
