function splitTopLevel(text,delimiter){
 const parts=[];let depth=0,start=0;
 for(let index=0;index<text.length;index++){
  const char=text[index];
  if(char==='（'||char==='(')depth++;
  else if(char==='）'||char===')')depth=Math.max(0,depth-1);
  else if(char===delimiter&&depth===0){parts.push(text.slice(start,index));start=index+1;}
 }
 parts.push(text.slice(start));
 return parts.map(part=>part.trim()).filter(Boolean);
}
export function splitRuleClauses(text){return splitTopLevel(text,'；');}
export function splitRuleTerms(clause){
 const cuts=[];let depth=0;
 for(let index=0;index<clause.length;index++){
  const char=clause[index];
  if(char==='（'||char==='(')depth++;
  else if(char==='）'||char===')')depth=Math.max(0,depth-1);
  else if(depth===0&&(char==='+'||char==='−')&&clause[index+1]===' '&&(clause[index-1]===' '||clause[index-1]==='）'||clause[index-1]===')'))cuts.push(index);
 }
 const starts=cuts.map(index=>clause[index-1]===' '?index-1:index),bounds=[0,...starts,clause.length],terms=[];
 for(let index=0;index<bounds.length-1;index++){
  const raw=clause.slice(bounds[index],bounds[index+1]),match=/^\s*([+−])\s+/.exec(raw);
  terms.push({sign:match?match[1]:'',sep:match?match[0]:'',text:(match?raw.slice(match[0].length):raw).trim()});
 }
 return terms.filter(term=>term.text);
}
// 长句按逗号/顿号断行，断点保留原符号，拼接回来与原文逐字一致。
function splitKeepMarks(text,marks){
 const parts=[];let depth=0,start=0;
 for(let index=0;index<text.length;index++){
  const char=text[index];
  if(char==='（'||char==='(')depth++;
  else if(char==='）'||char===')')depth=Math.max(0,depth-1);
  else if(depth===0&&marks.includes(char)){parts.push(text.slice(start,index+1));start=index+1;}
 }
 parts.push(text.slice(start));
 return parts.filter(part=>part.length);
}
export function splitRuleLines(text,limit=60){
 const lines=[];
 for(const part of splitKeepMarks(text,['，','、'])){
  const last=lines.length-1;
  if(last>=0&&lines[last].length+part.length<=limit)lines[last]+=part;
  else lines.push(part);
 }
 return lines;
}
export function joinRuleLines(lines){return lines.join('');}
export function parseAffinityRule(text=AFFINITY_RULE_TEXT){
 const clauses=splitRuleClauses(text);
 return {terms:splitRuleTerms(clauses[0]||''),notes:clauses.slice(1)};
}
export function joinAffinityRule({terms,notes}){
 const head=terms.map(term=>(term.sep||'')+term.text).join('');
 return [head,...notes].join('；');
}
// 「无记录（缺口）」与「有记录但低分」必须能区分：缺口只按有无聊天记录判断，不看分数高低。
export function scoreBucketState(bucket){
 if(bucket&&typeof bucket.averageAffinity==='number')return bucket.averageAffinity<40?'low':'scored';
 return bucket&&bucket.recorded?'no-score':'gap';
}
